CREATE SCHEMA IF NOT EXISTS inventory;

CREATE TABLE IF NOT EXISTS inventory.landed_costs (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    lc_number TEXT NOT NULL,
    company_id UUID NOT NULL,
    branch_id UUID,
    target_receipt_id UUID NOT NULL,
    transfer_id UUID,
    currency TEXT NOT NULL DEFAULT 'IDR',
    posting_date DATE NOT NULL,
    state landed_cost_state NOT NULL DEFAULT 'draft',
    amount_total NUMERIC(18, 2) NOT NULL DEFAULT 0,
    posting_state gl_posting_state NOT NULL DEFAULT 'pending',
    journal_id UUID,
    accounting_post_id UUID,
    posted_at TIMESTAMPTZ,
    notes TEXT,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_landed_costs_company_id_lc_number ON inventory.landed_costs (company_id, lc_number) WHERE (metadata->>'deleted_at') IS NULL;

CREATE INDEX IF NOT EXISTS idx_landed_costs_state ON inventory.landed_costs (state);

CREATE INDEX IF NOT EXISTS idx_landed_costs_posting_state ON inventory.landed_costs (posting_state);

CREATE INDEX IF NOT EXISTS idx_landed_costs_target_receipt_id ON inventory.landed_costs (target_receipt_id);

-- GIN index for audit metadata JSONB queries
CREATE INDEX IF NOT EXISTS idx_landed_costs_metadata_gin ON inventory.landed_costs USING GIN (metadata);
CREATE INDEX IF NOT EXISTS idx_landed_costs_metadata_deleted_at ON inventory.landed_costs ((metadata->>'deleted_at'));
CREATE INDEX IF NOT EXISTS idx_landed_costs_metadata_created_at ON inventory.landed_costs ((metadata->>'created_at'));
CREATE INDEX IF NOT EXISTS idx_landed_costs_metadata_updated_at ON inventory.landed_costs ((metadata->>'updated_at'));

-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION inventory.landed_costs_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS landed_costs_insert_audit ON inventory.landed_costs;
CREATE TRIGGER landed_costs_insert_audit BEFORE INSERT ON inventory.landed_costs
    FOR EACH ROW EXECUTE FUNCTION inventory.landed_costs_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS landed_costs_update_audit ON inventory.landed_costs;
CREATE TRIGGER landed_costs_update_audit BEFORE UPDATE ON inventory.landed_costs
    FOR EACH ROW EXECUTE FUNCTION inventory.landed_costs_audit_timestamp();
